from html.parser import HTMLParser


class _ResourceParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.seen = set()

    def handle_starttag(self, tag, attrs):
        attributes = dict(attrs)
        value = None
        if tag == "img":
            value = attributes.get("src")
        elif tag == "link":
            rel = attributes.get("rel") or ""
            if "preload" in rel.lower().split():
                value = attributes.get("href")
        if value is not None:
            value = value.strip()
            if value and value not in self.seen:
                self.seen.add(value)
                self.links.append(value)


def extract_preload_and_image_links(document):
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    parser = _ResourceParser()
    parser.feed(document)
    parser.close()
    return list(parser.links)

import copy
from concurrent.futures import ThreadPoolExecutor as _Executor


class Ticket:
    def __init__(self, future):
        self._future = future

    def result(self):
        return self._future.result()


class BatchRunner:
    def __init__(self, max_workers):
        if isinstance(max_workers, bool) or not isinstance(max_workers, int):
            raise TypeError("max_workers must be an integer")
        if max_workers <= 0:
            raise ValueError("max_workers must be positive")
        self._executor = _Executor(max_workers=max_workers)
        self._tickets = []
        self._closed = False

    def submit(self, function, *args, **kwargs):
        if self._closed:
            raise RuntimeError("runner is shut down")
        if not callable(function):
            raise TypeError("function must be callable")
        saved_args = copy.deepcopy(args)
        saved_kwargs = copy.deepcopy(kwargs)
        ticket = Ticket(self._executor.submit(function, *saved_args, **saved_kwargs))
        self._tickets.append(ticket)
        return ticket

    def gather(self):
        results = []
        first_error = None
        for ticket in self._tickets:
            try:
                results.append(ticket.result())
            except BaseException as error:
                results.append(None)
                if first_error is None:
                    first_error = error
        if first_error is not None:
            raise first_error
        return results

    def shutdown(self):
        if not self._closed:
            self._closed = True
            self._executor.shutdown(wait=True)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, traceback):
        self.shutdown()
        return False

import logging


class BaseUnit:
    def __init__(self, logger=None):
        if logger is not None and not isinstance(logger, logging.Logger):
            raise ValueError("logger must be a Logger")
        self._logger = logging.getLogger(__name__) if logger is None else logger
        self._state = "new"
        self._events = []

    @property
    def state(self):
        return self._state

    @property
    def events(self):
        return tuple(self._events)

    def _record(self, text):
        self._events.append(text)
        self._logger.debug(text)

    def initialize(self):
        if self._state != "new":
            raise RuntimeError("invalid transition")
        self._execute_initialization()
        self._state = "initialized"

    def start(self):
        if self._state != "initialized":
            raise RuntimeError("invalid transition")
        self._execute_start()
        self._state = "running"

    def stop(self):
        if self._state != "running":
            raise RuntimeError("invalid transition")
        self._execute_stop()
        self._state = "stopped"

    def _execute_initialization(self):
        self._record("base:initialization")

    def _execute_start(self):
        self._record("base:start")

    def _execute_stop(self):
        self._record("base:stop")


class AuditUnit(BaseUnit):
    def _execute_initialization(self):
        super()._execute_initialization()
        self._record("audit:initialization")

    def _execute_start(self):
        super()._execute_start()
        self._record("audit:start")

    def _execute_stop(self):
        super()._execute_stop()
        self._record("audit:stop")

    def load(self):
        return True

import copy


def _shape(matrix, name):
    if not isinstance(matrix, list):
        raise TypeError(f"{name} must be a list")
    if not matrix:
        return 0, 0
    if any(not isinstance(row, list) for row in matrix):
        raise TypeError(f"{name} rows must be lists")
    width = len(matrix[0])
    if any(len(row) != width for row in matrix):
        raise ValueError(f"{name} must be rectangular")
    return len(matrix), width


def stamp_matrix(base, patch, top, left, transparent=None):
    base_h, base_w = _shape(base, "base")
    patch_h, patch_w = _shape(patch, "patch")
    if isinstance(top, bool) or not isinstance(top, int):
        raise TypeError("top must be an integer")
    if isinstance(left, bool) or not isinstance(left, int):
        raise TypeError("left must be an integer")

    if patch_h and patch_w:
        if top < 0 or left < 0 or top + patch_h > base_h or left + patch_w > base_w:
            raise ValueError("patch does not fit")

    result = [copy.deepcopy(row) for row in base]
    for row_index, row in enumerate(patch):
        for column_index, value in enumerate(row):
            if value != transparent:
                result[top + row_index][left + column_index] = copy.deepcopy(value)
    return result

export interface Subscriber {
  id: string;
  name: string;
  email: string;
  active: boolean;
}

function copy(value: Subscriber): Subscriber {
  return {
    id: value.id,
    name: value.name,
    email: value.email,
    active: value.active,
  };
}

function seed(values: readonly Subscriber[]): Subscriber[] {
  const seen = new Set<string>();
  return values.map((value) => {
    if (value.id.length === 0) throw new RangeError("id must not be empty");
    if (seen.has(value.id)) throw new Error("duplicate subscriber");
    seen.add(value.id);
    return copy(value);
  });
}

export class SubscriberStore {
  private readonly v1: Subscriber[];
  private readonly v2: Subscriber[];

  constructor(v1: readonly Subscriber[] = [], v2: readonly Subscriber[] = []) {
    this.v1 = seed(v1);
    this.v2 = seed(v2);
  }

  list(): Subscriber[] {
    return this.v1.map(copy);
  }

  add(value: Subscriber): Subscriber {
    if (value.id.length === 0) throw new RangeError("id must not be empty");
    if (this.v2.some((item) => item.id === value.id)) {
      throw new Error("duplicate subscriber");
    }
    const stored = copy(value);
    this.v2.push(stored);
    return copy(stored);
  }

  remove(id: string): boolean {
    if (id.length === 0) throw new RangeError("id must not be empty");
    const index = this.v2.findIndex((item) => item.id === id);
    if (index < 0) return false;
    this.v2.splice(index, 1);
    return true;
  }

  update(value: Subscriber): Subscriber {
    if (value.id.length === 0) throw new RangeError("id must not be empty");
    const index = this.v2.findIndex((item) => item.id === value.id);
    if (index < 0) throw new Error("subscriber not found");
    this.v2[index] = copy(value);
    return copy(this.v2[index]);
  }
}

