export interface Dimensions {
  width: number;
  height: number;
}

export type DimensionListener = (current: Readonly<Dimensions>) => void;

function validate(value: Dimensions): void {
  if (
    !Number.isFinite(value.width) ||
    !Number.isFinite(value.height) ||
    !Number.isInteger(value.width) ||
    !Number.isInteger(value.height) ||
    value.width < 0 ||
    value.height < 0
  ) {
    throw new RangeError("dimensions must be finite non-negative integers");
  }
}

function copy(value: Dimensions): Dimensions {
  return { width: value.width, height: value.height };
}

export class DimensionLedger {
  private value: Dimensions;
  private readonly listeners: Array<{
    listener: DimensionListener;
    active: boolean;
  }> = [];

  constructor(initial: Dimensions) {
    validate(initial);
    this.value = copy(initial);
  }

  current(): Dimensions {
    return copy(this.value);
  }

  resize(next: Dimensions): boolean {
    validate(next);
    if (next.width === this.value.width && next.height === this.value.height) {
      return false;
    }
    this.value = copy(next);
    const current = this.listeners.filter((entry) => entry.active);
    for (const entry of current) {
      entry.listener(copy(this.value));
    }
    return true;
  }

  onChange(listener: DimensionListener): () => void {
    const entry = { listener, active: true };
    this.listeners.push(entry);
    return () => {
      entry.active = false;
    };
  }
}

export interface Preset {
  id: string;
  label: string;
  status: 'available' | 'withdrawn';
}

export interface PresetGroups {
  available: Preset[];
  withdrawn: Preset[];
}

function compareText(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function copy(preset: Preset): Preset {
  return {
    id: preset.id,
    label: preset.label,
    status: preset.status,
  };
}

export function groupPresets(input: readonly Preset[]): PresetGroups {
  const seen = new Set<string>();
  const result: PresetGroups = { available: [], withdrawn: [] };

  for (const preset of input) {
    if (preset.id.trim() === '' || preset.label.trim() === '') {
      throw new TypeError('Preset IDs and labels must be non-blank');
    }
    if (seen.has(preset.id)) {
      throw new RangeError(`Duplicate preset ID: ${preset.id}`);
    }
    seen.add(preset.id);
    result[preset.status].push(copy(preset));
  }

  const compare = (a: Preset, b: Preset): number =>
    compareText(a.label, b.label) || compareText(a.id, b.id);
  result.available.sort(compare);
  result.withdrawn.sort(compare);
  return result;
}

export interface BookInput {
  title: string;
  author: string;
  publishedYear: number;
  genre: string;
}

export interface Book extends BookInput {
  id: string;
  ownerId: string;
}

export type AddBookResult =
  | { ok: true; books: Book[]; book: Book }
  | { ok: false; errors: string[]; books: Book[] };

function copyBook(book: Book): Book {
  return {
    id: book.id,
    ownerId: book.ownerId,
    title: book.title,
    author: book.author,
    publishedYear: book.publishedYear,
    genre: book.genre,
  };
}

export function addBook(
  existing: readonly Book[],
  ownerId: string,
  id: string,
  input: BookInput,
): AddBookResult {
  const errors: string[] = [];
  const trimmedOwnerId = ownerId.trim();
  const trimmedId = id.trim();

  if (trimmedOwnerId === '') errors.push('ownerId');
  if (trimmedId === '') errors.push('id');
  if (input.title.trim() === '') errors.push('title');
  if (input.author.trim() === '') errors.push('author');
  if (
    !Number.isInteger(input.publishedYear) ||
    input.publishedYear < 1450 ||
    input.publishedYear > 2100
  ) {
    errors.push('publishedYear');
  }
  if (input.genre.trim() === '') errors.push('genre');
  if (existing.some((book) => book.id === trimmedId)) {
    errors.push('duplicateId');
  }

  const copies = existing.map(copyBook);
  if (errors.length > 0) {
    return { ok: false, errors, books: copies };
  }

  const created: Book = {
    id: trimmedId,
    ownerId: trimmedOwnerId,
    title: input.title.trim(),
    author: input.author.trim(),
    publishedYear: input.publishedYear,
    genre: input.genre.trim(),
  };
  return {
    ok: true,
    books: [...copies, copyBook(created)],
    book: copyBook(created),
  };
}

'use strict';

function createGlossary(entries) {
  if (!Array.isArray(entries)) throw new TypeError('entries must be an array');
  const glossary = new Map();

  for (let i = 0; i < entries.length; i += 1) {
    const entry = entries[i];
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new TypeError('entry must be an object');
    }
    if (typeof entry.term !== 'string' || entry.term.trim() === '') {
      throw new TypeError('term must be a nonempty string');
    }
    if (!Array.isArray(entry.categories)) {
      throw new TypeError('categories must contain nonempty strings');
    }

    const categories = [];
    for (let j = 0; j < entry.categories.length; j += 1) {
      const category = entry.categories[j];
      if (typeof category !== 'string' || category.trim() === '') {
        throw new TypeError('categories must contain nonempty strings');
      }
      categories.push(category.trim());
    }

    const term = entry.term.trim();
    const key = term.toLowerCase();
    if (glossary.has(key)) throw new Error(`Duplicate term: ${term}`);
    glossary.set(key, { canonical: term, categories });
  }

  function review(tokens) {
    if (!Array.isArray(tokens)) throw new TypeError('tokens must be an array of strings');
    const results = [];
    for (let i = 0; i < tokens.length; i += 1) {
      const token = tokens[i];
      if (typeof token !== 'string') {
        throw new TypeError('tokens must be an array of strings');
      }
      const found = glossary.get(token.toLowerCase());
      results.push(found
        ? { token, known: true, canonical: found.canonical, categories: [...found.categories] }
        : { token, known: false, canonical: null, categories: [] });
    }
    return results;
  }

  return { review };
}

module.exports = { createGlossary };

'use strict';

function splitEpochNanos(value) {
  let nanos;
  if (typeof value === 'bigint') nanos = value;
  else if (typeof value === 'string' && /^\d+$/.test(value)) nanos = BigInt(value);
  else throw new TypeError('value must be a non-negative bigint or decimal string');

  if (nanos < 0n) throw new RangeError('value must be non-negative');
  const milliseconds = nanos / 1000000n;
  if (milliseconds > BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new RangeError('millisecond component is too large');
  }
  return {
    epochMilliseconds: Number(milliseconds),
    remainderNanoseconds: Number(nanos % 1000000n)
  };
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function validateMeasurement(value) {
  if (!isRecord(value) ||
      typeof value.device !== 'string' || value.device.length === 0 ||
      typeof value.metric !== 'string' || value.metric.length === 0 ||
      typeof value.value !== 'number' || !Number.isFinite(value.value)) {
    throw new TypeError('invalid measurement');
  }
  try {
    return splitEpochNanos(value.atNanos);
  } catch (error) {
    throw new TypeError('invalid measurement');
  }
}

class FeedMapper {
  constructor(useModernProtocol) {
    this.useModernProtocol = Boolean(useModernProtocol);
  }

  _measurements(packet) {
    if (!isRecord(packet)) throw new TypeError('invalid packet');
    const singular = this.useModernProtocol ? 'sample' : 'reading';
    const plural = this.useModernProtocol ? 'samples' : 'readings';
    if (packet.kind !== singular && packet.kind !== plural) {
      throw new TypeError('unsupported packet');
    }
    if (packet.kind === plural) {
      if (!Array.isArray(packet.data)) {
        throw new TypeError('plural packet data must be an array');
      }
      return packet.data;
    }
    return [packet.data];
  }

  canHandle(packet) {
    try {
      const measurements = this._measurements(packet);
      for (let i = 0; i < measurements.length; i += 1) {
        validateMeasurement(measurements[i]);
      }
      return true;
    } catch (error) {
      return false;
    }
  }

  getTopics(devices) {
    if (!Array.isArray(devices)) throw new TypeError('devices must be an array');
    const seen = new Set();
    const topics = [];
    const prefix = this.useModernProtocol ? 'modern/' : 'legacy/';
    for (let i = 0; i < devices.length; i += 1) {
      const device = devices[i];
      if (typeof device !== 'string' || device.length === 0) {
        throw new TypeError('device names must be non-empty strings');
      }
      if (!seen.has(device)) {
        seen.add(device);
        topics.push(prefix + device);
      }
    }
    return topics;
  }

  *map(packet, receivedSequence) {
    if (!Number.isSafeInteger(receivedSequence) || receivedSequence < 0) {
      throw new TypeError('receivedSequence must be a non-negative safe integer');
    }
    const measurements = this._measurements(packet);
    const validated = [];
    for (let i = 0; i < measurements.length; i += 1) {
      const measurement = measurements[i];
      validated.push({ measurement, timestamp: validateMeasurement(measurement) });
    }
    for (const item of validated) {
      yield {
        device: item.measurement.device,
        metric: item.measurement.metric,
        value: item.measurement.value,
        timestamp: {
          epochMilliseconds: item.timestamp.epochMilliseconds,
          remainderNanoseconds: item.timestamp.remainderNanoseconds
        },
        receivedSequence
      };
    }
  }
}

module.exports = { splitEpochNanos, FeedMapper };

'use strict';

function createRecipeBook(initialRecipes) {
  if (!Array.isArray(initialRecipes)) {
    throw new TypeError('initialRecipes must be an array');
  }
  const recipes = new Map();

  function cleanText(value, field) {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new TypeError(field + ' must be a non-empty string');
    }
    return value.trim();
  }

  function cleanIngredients(value) {
    if (!Array.isArray(value)) throw new TypeError('ingredients must be an array');
    const result = [];
    for (let i = 0; i < value.length; i += 1) {
      result.push(cleanText(value[i], 'ingredient'));
    }
    return result;
  }

  function cleanRecipe(value) {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      throw new TypeError('recipe must be an object');
    }
    return {
      id: cleanText(value.id, 'id'),
      title: cleanText(value.title, 'title'),
      ingredients: cleanIngredients(value.ingredients)
    };
  }

  function copy(recipe) {
    return {
      id: recipe.id,
      title: recipe.title,
      ingredients: [...recipe.ingredients]
    };
  }

  for (let i = 0; i < initialRecipes.length; i += 1) {
    const recipe = cleanRecipe(initialRecipes[i]);
    if (recipes.has(recipe.id)) throw new RangeError('duplicate recipe id');
    recipes.set(recipe.id, recipe);
  }

  return {
    add(value) {
      const recipe = cleanRecipe(value);
      if (recipes.has(recipe.id)) throw new RangeError('duplicate recipe id');
      recipes.set(recipe.id, recipe);
      return copy(recipe);
    },
    get(id) {
      const key = cleanText(id, 'id');
      return recipes.has(key) ? copy(recipes.get(key)) : null;
    },
    update(id, changes) {
      const key = cleanText(id, 'id');
      if (changes === null || typeof changes !== 'object' || Array.isArray(changes)) {
        throw new TypeError('changes must be an object');
      }
      if (Object.prototype.hasOwnProperty.call(changes, 'id')) {
        throw new TypeError('id cannot be updated');
      }
      const hasTitle = Object.prototype.hasOwnProperty.call(changes, 'title');
      const hasIngredients = Object.prototype.hasOwnProperty.call(changes, 'ingredients');
      const title = hasTitle ? cleanText(changes.title, 'title') : undefined;
      const ingredients = hasIngredients ? cleanIngredients(changes.ingredients) : undefined;
      if (!recipes.has(key)) return null;
      const current = recipes.get(key);
      const next = {
        id: current.id,
        title: hasTitle ? title : current.title,
        ingredients: hasIngredients ? ingredients : [...current.ingredients]
      };
      recipes.set(key, next);
      return copy(next);
    },
    remove(id) {
      return recipes.delete(cleanText(id, 'id'));
    },
    list() {
      return Array.from(recipes.values(), copy);
    }
  };
}

module.exports = { createRecipeBook };

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EvalError {
    EmptyExpression,
    UnexpectedToken(usize),
    MissingClosingParen,
    DivisionByZero,
    Overflow,
}

pub fn evaluate(source: &str) -> Result<i64, EvalError> {
    let mut parser = Parser {
        source: source.as_bytes(),
        position: 0,
    };
    parser.skip_space();
    if parser.position == parser.source.len() {
        return Err(EvalError::EmptyExpression);
    }
    let value = parser.parse_sum()?;
    parser.skip_space();
    if parser.position != parser.source.len() {
        return Err(EvalError::UnexpectedToken(parser.position));
    }
    Ok(value)
}

struct Parser<'a> {
    source: &'a [u8],
    position: usize,
}

impl Parser<'_> {
    fn skip_space(&mut self) {
        while self
            .source
            .get(self.position)
            .is_some_and(|byte| byte.is_ascii_whitespace())
        {
            self.position += 1;
        }
    }

    fn take(&mut self, expected: u8) -> bool {
        self.skip_space();
        if self.source.get(self.position) == Some(&expected) {
            self.position += 1;
            true
        } else {
            false
        }
    }

    fn parse_sum(&mut self) -> Result<i64, EvalError> {
        let mut value = self.parse_product()?;
        loop {
            if self.take(b'+') {
                value = value
                    .checked_add(self.parse_product()?)
                    .ok_or(EvalError::Overflow)?;
            } else if self.take(b'-') {
                value = value
                    .checked_sub(self.parse_product()?)
                    .ok_or(EvalError::Overflow)?;
            } else {
                return Ok(value);
            }
        }
    }

    fn parse_product(&mut self) -> Result<i64, EvalError> {
        let mut value = self.parse_unary()?;
        loop {
            if self.take(b'*') {
                value = value
                    .checked_mul(self.parse_unary()?)
                    .ok_or(EvalError::Overflow)?;
            } else if self.take(b'/') {
                let divisor = self.parse_unary()?;
                if divisor == 0 {
                    return Err(EvalError::DivisionByZero);
                }
                value = value.checked_div(divisor).ok_or(EvalError::Overflow)?;
            } else {
                return Ok(value);
            }
        }
    }

    fn parse_unary(&mut self) -> Result<i64, EvalError> {
        if self.take(b'+') {
            self.parse_unary()
        } else if self.take(b'-') {
            self.parse_unary()?
                .checked_neg()
                .ok_or(EvalError::Overflow)
        } else {
            self.parse_atom()
        }
    }

    fn parse_atom(&mut self) -> Result<i64, EvalError> {
        self.skip_space();
        if self.take(b'(') {
            self.skip_space();
            if self.position == self.source.len() {
                return Err(EvalError::MissingClosingParen);
            }
            if self.source.get(self.position) == Some(&b')') {
                return Err(EvalError::UnexpectedToken(self.position));
            }
            let value = self.parse_sum()?;
            self.skip_space();
            match self.source.get(self.position) {
                Some(b')') => {
                    self.position += 1;
                    return Ok(value);
                }
                Some(_) => return Err(EvalError::UnexpectedToken(self.position)),
                None => return Err(EvalError::MissingClosingParen),
            }
        }

        self.skip_space();
        let start = self.position;
        let mut value = 0i64;
        let mut found = false;
        while let Some(byte @ b'0'..=b'9') = self.source.get(self.position).copied() {
            found = true;
            value = value
                .checked_mul(10)
                .and_then(|number| number.checked_add((byte - b'0') as i64))
                .ok_or(EvalError::Overflow)?;
            self.position += 1;
        }
        if found {
            Ok(value)
        } else {
            Err(EvalError::UnexpectedToken(start))
        }
    }
}

use std::collections::BTreeSet;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ModelType {
    Text,
    Integer,
    Decimal,
    Flag,
    Named(String),
    Sequence(Box<ModelType>),
    Dictionary(Box<ModelType>),
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Property {
    pub name: String,
    pub model_type: ModelType,
    pub required: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Model {
    pub name: String,
    pub properties: Vec<Property>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum GenerationError {
    InvalidIdentifier(String),
    DuplicateModel(String),
    DuplicateProperty { model: String, property: String },
    UnknownModel(String),
}

fn valid_identifier(value: &str) -> bool {
    let mut chars = value.chars();
    match chars.next() {
        Some(c) if c.is_ascii_alphabetic() || c == '_' => {}
        _ => return false,
    }
    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

fn validate_type(ty: &ModelType, names: &BTreeSet<&str>) -> Result<(), GenerationError> {
    match ty {
        ModelType::Named(name) if !names.contains(name.as_str()) => {
            Err(GenerationError::UnknownModel(name.clone()))
        }
        ModelType::Sequence(inner) | ModelType::Dictionary(inner) => validate_type(inner, names),
        _ => Ok(()),
    }
}

fn render_type(ty: &ModelType) -> String {
    match ty {
        ModelType::Text => "String".to_string(),
        ModelType::Integer => "i64".to_string(),
        ModelType::Decimal => "f64".to_string(),
        ModelType::Flag => "bool".to_string(),
        ModelType::Named(name) => name.clone(),
        ModelType::Sequence(inner) => format!("Vec<{}>", render_type(inner)),
        ModelType::Dictionary(inner) => format!(
            "std::collections::BTreeMap<String, {}>",
            render_type(inner)
        ),
    }
}

pub fn emit_rust_models(models: &[Model]) -> Result<String, GenerationError> {
    let all_names: BTreeSet<&str> = models.iter().map(|model| model.name.as_str()).collect();
    let mut seen_models = BTreeSet::new();

    for model in models {
        if !valid_identifier(&model.name) {
            return Err(GenerationError::InvalidIdentifier(model.name.clone()));
        }
        if !seen_models.insert(model.name.as_str()) {
            return Err(GenerationError::DuplicateModel(model.name.clone()));
        }

        let mut properties = BTreeSet::new();
        for property in &model.properties {
            if !valid_identifier(&property.name) {
                return Err(GenerationError::InvalidIdentifier(property.name.clone()));
            }
            if !properties.insert(property.name.as_str()) {
                return Err(GenerationError::DuplicateProperty {
                    model: model.name.clone(),
                    property: property.name.clone(),
                });
            }
            validate_type(&property.model_type, &all_names)?;
        }
    }

    let mut output = String::new();
    for (index, model) in models.iter().enumerate() {
        if index > 0 {
            output.push('\n');
        }
        output.push_str("#[derive(Clone, Debug, PartialEq)]\n");
        output.push_str(&format!("pub struct {} {{\n", model.name));
        for property in &model.properties {
            let mut ty = render_type(&property.model_type);
            if !property.required {
                ty = format!("Option<{}>", ty);
            }
            output.push_str(&format!("    pub {}: {},\n", property.name, ty));
        }
        output.push_str("}\n");
    }
    Ok(output)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verb {
    Read,
    Write,
    Replace,
    Remove,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Packet {
    pub verb: Verb,
    pub route: String,
    pub attributes: Vec<(String, String)>,
    pub payload: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TextPacket {
    pub verb: Verb,
    pub route: String,
    pub attributes: Vec<(String, String)>,
    pub payload: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParseError {
    MissingSeparator,
    InvalidHeaderUtf8,
    InvalidStartLine,
    UnknownVerb,
    InvalidAttribute,
    InvalidBodyUtf8,
}

pub fn parse_packet(input: &[u8]) -> Result<Packet, ParseError> {
    let split = input
        .windows(2)
        .position(|window| window == b"\n\n")
        .ok_or(ParseError::MissingSeparator)?;
    let header = std::str::from_utf8(&input[..split])
        .map_err(|_| ParseError::InvalidHeaderUtf8)?;
    let mut lines = header.split('\n');
    let start_line = lines.next().ok_or(ParseError::InvalidStartLine)?;
    let mut start = start_line.split(' ');
    let verb_text = start.next().ok_or(ParseError::InvalidStartLine)?;
    let route = start
        .next()
        .filter(|value| !value.is_empty())
        .ok_or(ParseError::InvalidStartLine)?;
    if verb_text.is_empty() || start.next().is_some() {
        return Err(ParseError::InvalidStartLine);
    }
    let verb = match verb_text {
        "READ" => Verb::Read,
        "WRITE" => Verb::Write,
        "REPLACE" => Verb::Replace,
        "REMOVE" => Verb::Remove,
        _ => return Err(ParseError::UnknownVerb),
    };
    let mut attributes = Vec::new();
    for line in lines {
        let (name, value) = line.split_once(':').ok_or(ParseError::InvalidAttribute)?;
        if name.is_empty() {
            return Err(ParseError::InvalidAttribute);
        }
        attributes.push((name.to_owned(), value.to_owned()));
    }
    Ok(Packet {
        verb,
        route: route.to_owned(),
        attributes,
        payload: input[split + 2..].to_vec(),
    })
}

pub fn parse_text_packet(input: &[u8]) -> Result<TextPacket, ParseError> {
    let packet = parse_packet(input)?;
    let payload = String::from_utf8(packet.payload)
        .map_err(|_| ParseError::InvalidBodyUtf8)?;
    Ok(TextPacket {
        verb: packet.verb,
        route: packet.route,
        attributes: packet.attributes,
        payload,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Channel {
    Email,
    Sms,
    Dashboard,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NoticeRule {
    pub id: u64,
    pub channels: Vec<Channel>,
    pub subject_prefix: String,
    pub expires_after: Option<u32>,
    pub tags: Option<Vec<String>>,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct RulePatch {
    pub expires_after: Option<Option<u32>>,
    pub tags: Option<Option<Vec<String>>>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RuleError {
    InvalidId,
    NoChannels,
    EmptyPrefix,
    ZeroExpiry,
    EmptyTag,
}

fn validate_rule(rule: &NoticeRule) -> Result<(), RuleError> {
    if rule.id == 0 {
        return Err(RuleError::InvalidId);
    }
    if rule.channels.is_empty() {
        return Err(RuleError::NoChannels);
    }
    if rule.subject_prefix.trim().is_empty() {
        return Err(RuleError::EmptyPrefix);
    }
    if rule.expires_after == Some(0) {
        return Err(RuleError::ZeroExpiry);
    }
    if rule
        .tags
        .as_ref()
        .is_some_and(|tags| tags.iter().any(|tag| tag.trim().is_empty()))
    {
        return Err(RuleError::EmptyTag);
    }
    Ok(())
}

pub fn create_rule(
    id: u64,
    channels: Vec<Channel>,
    subject_prefix: String,
) -> Result<NoticeRule, RuleError> {
    let rule = NoticeRule {
        id,
        channels,
        subject_prefix,
        expires_after: None,
        tags: None,
    };
    validate_rule(&rule)?;
    Ok(rule)
}

pub fn update_rule(rule: &mut NoticeRule, patch: RulePatch) -> Result<(), RuleError> {
    let mut candidate = rule.clone();
    if let Some(value) = patch.expires_after {
        candidate.expires_after = value;
    }
    if let Some(value) = patch.tags {
        candidate.tags = value;
    }
    validate_rule(&candidate)?;
    *rule = candidate;
    Ok(())
}

pub fn ordered_rules(rules: &[NoticeRule]) -> Vec<&NoticeRule> {
    let mut result: Vec<_> = rules.iter().collect();
    result.sort_by_key(|rule| rule.id);
    result
}

use std::collections::HashSet;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ProfileCard {
    pub code: String,
    pub label: String,
    pub summary: String,
    pub category: String,
}

fn trim_ascii(value: &str) -> &str {
    value.trim_matches(|c: char| c.is_ascii_whitespace())
}

pub fn parse_profile_card(input: &str) -> Result<ProfileCard, &'static str> {
    let mut code = None;
    let mut label = None;
    let mut summary = None;
    let mut category = None;
    let mut seen = HashSet::new();

    for raw in input.lines() {
        let line = trim_ascii(raw);
        if line.is_empty() {
            continue;
        }
        if line.matches('=').count() != 1 {
            return Err("malformed assignment");
        }
        let (key, value) = line.split_once('=').ok_or("malformed assignment")?;
        let key = trim_ascii(key);
        let value = trim_ascii(value);
        if key.is_empty() {
            return Err("empty key");
        }
        if !seen.insert(key.to_string()) {
            return Err("duplicate key");
        }
        match key {
            "code" => code = Some(value.to_string()),
            "label" => label = Some(value.to_string()),
            "summary" => summary = Some(value.to_string()),
            "category" => category = Some(value.to_string()),
            _ => {}
        }
    }

    Ok(ProfileCard {
        code: code.ok_or("missing code")?,
        label: label.ok_or("missing label")?,
        summary: summary.ok_or("missing summary")?,
        category: category.ok_or("missing category")?,
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LookupError {
    EmptyKey,
    MalformedEntry { index: usize },
    ConflictingValues,
}

fn trim_ascii(value: &str) -> &str {
    value.trim_matches(|c: char| c.is_ascii_whitespace())
}

pub fn lookup_setting(
    entries: &[(String, String)],
    key: &str,
) -> Result<Option<String>, LookupError> {
    let key = trim_ascii(key);
    if key.is_empty() {
        return Err(LookupError::EmptyKey);
    }

    for (index, (entry_key, _)) in entries.iter().enumerate() {
        let entry_key = trim_ascii(entry_key);
        if entry_key.is_empty() || entry_key.chars().any(|c| c.is_ascii_control()) {
            return Err(LookupError::MalformedEntry { index });
        }
    }

    let mut found: Option<String> = None;
    for (entry_key, entry_value) in entries {
        let entry_key = trim_ascii(entry_key);
        if entry_key.eq_ignore_ascii_case(key) {
            let value = trim_ascii(entry_value);
            match &found {
                Some(previous) if previous != value => {
                    return Err(LookupError::ConflictingValues);
                }
                None => found = Some(value.to_owned()),
                _ => {}
            }
        }
    }
    Ok(found)
}
